style.img:
context where
      currentColor does NOT inherit the page text color (it falls back to
      black and never adapts to dark mode).  A prefers-color-scheme custom
      property DOES fire, so route every text/stroke through --ink. */
   svg { --ink: #1f2328; }
   .box-author   { fill: #dbeafe; stroke: #3b82f6; stroke-width: 1.5; rx: 7; }
   .box-internal { fill: #dcfce7; stroke: #22c55e; stroke-width: 1.5; }
   .box-external { fill: #fef9c3; stroke: #eab308; stroke-width: 1.5; }
   .box-decision { fill: #f3e8ff; stroke: #a855f7; stroke-width: 1.5; }
   .lbl-head  { font-family: ui-sans-serif, system-ui, -apple-system,
                BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                font-size: 12.5px; font-weight: 700; fill: var(--ink); }
   .lbl-body  { font-family: ui-sans-serif, system-ui, -apple-system,
                BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                font-size: 11px; fill: var(--ink); opacity: 0.75; }
   .lbl-tag   { font-family: ui-sans-serif, system-ui, -apple-system,
                BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                font-size: 10.5px; font-style: italic;
                fill: var(--ink); opacity: 0.6; }
   .arrow     { stroke: var(--ink); stroke-width: 1.6;
                stroke-opacity: 0.5; fill: none;
                marker-end: url(#arr); }
   .arrowhead { fill: var(--ink); opacity: 0.5; }
   .divider   { stroke: var(--ink); stroke-opacity: 0.12; stroke-width: 1; }
   .title     { font-family: ui-sans-serif, system-ui, -apple-system,
                BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                font-size: 13.5px; font-weight: 700;
                fill: var(--ink); }
   @media (prefers-color-scheme: dark) {
     svg { --ink: #e6edf3; }
     .box-author   { fill: #1e3a5f; stroke: #60a5fa; }
     .box-internal { fill: #14391f; stroke: #4ade80; }
     .box-external { fill: #3b2f07; stroke: #fbbf24; }
     .box-decision { fill: #2e1a47; stroke: #c084fc; }
   }
